const SUB = {
  research: 'Top five UX research use cases.',
  design: 'Top five design use cases, from the skills in the pipeline.',
  ops: 'One use case for each phase of the design thinking cycle.',
};

const ALL_SKILLS = [...SKILLS_A, ...SKILLS_B, ...SKILLS_C];
const skillByName = (name) => ALL_SKILLS.find((s) => s.name === name);

const $ = (id) => document.getElementById(id);
function el(tag, cls, text) {
  const n = document.createElement(tag);
  if (cls) n.className = cls;
  if (text !== undefined) n.textContent = text;
  return n;
}

const state = { agent: null };

function renderAgents() {
  const wrap = $('agents');
  wrap.textContent = '';
  AGENTS.forEach((a) => {
    const b = el('button', 'door ' + a.key);
    b.type = 'button';
    b.setAttribute('aria-pressed', String(state.agent === a.key));
    const top = el('div', 'top');
    top.appendChild(el('h3', '', a.name));
    top.appendChild(el('span', 'count', a.skills.length + ' skills'));
    b.appendChild(top);
    b.appendChild(el('p', '', a.blurb));
    b.appendChild(el('span', 'hint', state.agent === a.key ? 'Selected' : a.hint));
    b.addEventListener('click', () => selectAgent(a.key));
    wrap.appendChild(b);
  });
}

function selectAgent(key) {
  state.agent = key;
  renderAgents();
  renderUseCases();
  $('uc-sub').textContent = SUB[key];
}

function renderUseCases() {
  const list = $('ucs');
  list.textContent = '';
  if (!state.agent) {
    list.appendChild(el('li', 'empty', 'Pick a role above to see its top use cases. You can also type a question below.'));
    return;
  }
  ROLE_CASES[state.agent].forEach((c, i) => {
    const li = el('li');
    const card = el('article', 'uc ' + state.agent);
    const top = el('div', 'uc-top');
    top.appendChild(el('span', 'rank', 'No. ' + (i + 1)));
    if (c.phase) top.appendChild(el('span', 'phase', c.phase));
    card.appendChild(top);
    card.appendChild(el('strong', '', c.title));
    card.appendChild(el('span', 'what', c.what));
    card.appendChild(el('span', 'skill', c.skill));
    card.appendChild(el('div', 'ask-line', c.ask));
    li.appendChild(card);
    list.appendChild(li);
  });
}

// Full phrases score 3; longer words inside a phrase score 1.
function route(text) {
  const t = text.toLowerCase();
  let best = null;
  ROUTES.forEach((row) => {
    let score = 0;
    const hits = [];
    row.p.forEach((ph) => {
      if (t.includes(ph)) { score += 3; hits.push(ph); }
    });
    const words = new Set(row.p.join(' ').split(/[^a-z']+/).filter((w) => w.length >= 5 && !STOP.has(w)));
    words.forEach((w) => {
      if (t.includes(w) && !hits.some((h) => h.includes(w))) { score += 1; hits.push(w); }
    });
    if (score > 0 && (!best || score > best.score)) best = { row, score, hits };
  });
  return best;
}

// The page matches the question against the skill list. It does not call Claude.
const SKILL_PAGES = {
  'ux-research': 'agents/researcher/',
  'design-thinking-ux': 'agents/pipeline/',
  'ux-research-master': 'agents/designer/',
  'ux-install-all-skills': 'get-started/',
};

function skillHref(slug) {
  if (SKILL_PAGES[slug]) return SKILL_PAGES[slug];
  const onSite = ['ab-test-planner', 'accessibility-review', 'adoption-check', 'anti-sycophancy', 'assumption-mapper', 'brand-operator-ux-persona', 'brand-prototype', 'competitive-analysis', 'creator-affiliate-ux-persona', 'data-analyze', 'design-system', 'findings-publish', 'frame-maintenance', 'heuristic-evaluation', 'ideate', 'measurable-check', 'panel-planner', 'partner-prototype', 'persona-check', 'prototype-handoff', 'research-builder', 'research-intake', 'research-planner', 'research-synthesis', 'study-summary', 'synthesize-research', 'talk-to-users', 'test-loopback', 'test-plan', 'user-context', 'user-personas', 'user-research', 'ux-critique', 'ux-prototyping', 'write-spec'];
  return onSite.indexOf(slug) >= 0 ? 'skills/' + slug + '/' : '';
}

function askQuestion(text) {
  const out = $('routed');
  out.textContent = '';
  const question = text.trim();
  if (!question) {
    out.textContent = 'Type a question first.';
    return;
  }
  const hit = route(question);
  if (!hit) {
    out.textContent = 'Nothing matched. Ask one question first: what decision does this unlock?';
    return;
  }

  const skill = skillByName(hit.row.s);
  const head = el('div', 'answer-head');
  head.appendChild(document.createTextNode('Use'));
  const href = skillHref(hit.row.s);
  const name = href ? el('a', '', hit.row.s) : el('b', '', hit.row.s);
  if (href) name.href = href;
  head.appendChild(name);
  if (skill && skill.stage) head.appendChild(el('span', 'phase', skill.stage));
  out.appendChild(head);

  const body = el('div', 'answer-body');
  body.appendChild(el('p', '', skill ? skill.purpose : 'This question routes to ' + hit.row.s + '.'));
  if (skill && skill.enterNeeds) body.appendChild(el('p', '', 'It needs: ' + skill.enterNeeds));
  if (skill && skill.produces) body.appendChild(el('p', '', 'You get: ' + skill.produces));
  body.appendChild(el('p', 'mono', 'use ' + hit.row.s));
  out.appendChild(body);

  const why = el('p', 'match-meta');
  const phrase = hit.hits && hit.hits[0] ? hit.hits[0] : '';
  why.textContent = (phrase ? 'Matched “' + phrase + '”. ' : '') + (hit.row.r ? 'Runner-up: ' + hit.row.r + '.' : 'No close runner-up.');
  out.appendChild(why);
}

function buildExamples() {
  const wrap = $('examples');
  EXAMPLES.forEach((ex) => {
    const b = el('button', 'chip', ex);
    b.type = 'button';
    b.addEventListener('click', () => { $('q').value = ex; askQuestion(ex); });
    wrap.appendChild(b);
  });
}

// Copy buttons: the clipboard needs a click, and a refusal falls back to a label.
document.querySelectorAll('button[data-copy]').forEach((b) => {
  b.addEventListener('click', async () => {
    const text = b.dataset.copy;
    try {
      await navigator.clipboard.writeText(text);
      b.textContent = 'Copied';
    } catch (e) {
      b.textContent = 'Select the text';
    }
    setTimeout(() => { b.textContent = 'Copy'; }, 1600);
  });
});

$('go').addEventListener('click', () => askQuestion($('q').value));
$('q').addEventListener('keydown', (e) => { if (e.key === 'Enter') askQuestion($('q').value); });

renderAgents();
renderUseCases();
buildExamples();
